values.value:
{
	"fields":[
		{
			"apiName": "mdpe_14885_folder",
			"label": "IS 14885 Details",
			"type": "folder",
			"iconColor": "blue",
			"controllingField": "Standard",
			"controllingValues": [
				"MDPE Pipe"
			],
			"modalConfigsByValue": {
				"MDPE Pipe": {
                    "title": "GENERAL DETAILS - IS 14885",
                    "modalFields":[
                        {
							"id": "mdpe_setup_section",
							"label": "Step 1: Configuration Setup",
							"expanded": true,
							"fields": [
								{
								"apiName": "mdpe_pipe_count",
								"label": "Number of Line items",
								"type": "number",
								"colSpan": 3,
								"defaultValue": 1,
								"min": 1,
								"max": 10
								},
								{
									"apiName": "mdpe_Inspection_Commission",
									"label": "Inspection & Commission %",
									"type": "number",
									"colSpan":3
								},
								{
									"apiName": "mdpe_Interest_Charges_on_Payment_type",
									"label": "No of Days for Payment",
									"type": "number",
									"colSpan":3
								},
								{
									"apiName": "mdpe_Interest_Charges_on_Payment",
									"label": "Interest charges % per Annum",
									"type": "number",
									"colSpan":3
								},
								{
									"apiName": "mdpe_Type_of_transportation",
									"label": "Type of Transaportation",
									"type": "picklist",
									"options":["F.O.R (Freight on Road)","Ex-works"],
									"pushToParentApiName":"freight_incoterms_hdpe",
									"colSpan":3
								},
								{
									"apiName": "mdpe_Type_of_FOR",
									"label": "F.O.R (Freight on Road)",
									"type": "picklist",
									"options":["Per Meter","Lump Sum"],
									"controllingField":"mdpe_Type_of_transportation",
									"controllingValues":["F.O.R (Freight on Road)"],
									"colSpan":3
								},
								{
									"apiName": "mdpe_LumpSum_Amount",
									"label": "Lump Sum",
									"type": "number",
									"controllingField":"mdpe_Type_of_FOR",
									"controllingValues":["Lump Sum"],
									"colSpan":3
								}
							]
						},
						{
							"id": "mdpe_PE_G_and_PR_Selection_1",
							"label": "Step 2: Pipe Data Entry",
							"expanded": true,
							"controllingField": "mdpe_pipe_count",
							"controllingValues": [">=1"],
							"fields": [
								{
									"apiName": "mdpe_vertical_pipe_grid",
									"type": "column-repeater",
									"countApiName": "mdpe_pipe_count",
									"maxColumns": 10,
									"fields": [
										{
											"apiName": "mdpe_SDR_Grade_select",
											"label": "SDR Grade",
											"type": "picklist",
											"required": true,
											"options": [
												"SDR 9","SDR 11","SDR 13.6","SDR 17"
											]
										},
										{
											"apiName": "mdpe_Nominal_Dia",
											"label": "Nominal Dia",
											"type": "picklist",
											"controllingFields": ["mdpe_SDR_Grade_select"],
											"required": true,
											"options": [
												"16","20","25","32","40","50","63","75","90","110","125","140","160","180","200","225","250","280","315"
											],
											"dependentOptionsMap":{
												"SDR 9":["16","20","25","32","40","50","63","75","90","110","125","140","160","180","200","225","250","280","315"],
												"SDR 11":["16","20","25","32","40","50","63","75","90","110","125","140","160","180","200","225","250","280","315"],
												"SDR 13.6":["16","20","25","32","40","50","63","75","90","110","125","140","160","180","200","225","250","280","315"],
                                                "SDR 17":["32","40","50","63","75","90","110","125","140","160","180","200","225","250","280","315"]
											}
										},
										{
											"apiName": "mdpe_unit_of_messurment",
											"label": "UOM",
											"required": true,
											"type": "picklist",
											"options": [
												"mtr","Km"
											]
										},
										{
											"apiName": "mdpe_BOQ_Quantity",
											"label": "BOQ QTY",
											"required": true,
											"type": "number"
										},
										{
											"apiName": "mdpe_len_of_coil_pipe",
											"label": "Length of Coil/Pipe (mtr)",
											"required": true,
											"type": "number"
										},
										{
											"apiName": "mdpe_type_of_pipe",
											"label": "Type of Pipe",
											"type": "picklist",
											"options": [
												"Straight","Coil"
											],
											"defaultValue":"Straight"
										},
										{
											"apiName": "mdpe_No_of_Coil_Pipe",
											"label": "No. of Coil/Pipe",
											"type": "number",
											"readOnly": true,
											"formula": "Math.ceil(mdpe_unit_of_messurment == 'mtr' ? (mdpe_BOQ_Quantity / mdpe_len_of_coil_pipe) : mdpe_unit_of_messurment == 'Km' ? ((mdpe_BOQ_Quantity * 1000) / mdpe_len_of_coil_pipe): 0)"
										},
										{
											"apiName": "mdpe_Weight_mtrs",
											"label": "Weight/mtrs",
											"type": "number",
											"lookupWeight": true,
											"readOnly":true,
											"controllingFields": ["mdpe_SDR_Grade_select","mdpe_Nominal_Dia"],
											"weightMap": {"SDR 9|16":0.124,"SDR 9|20":0.165,"SDR 9|25":0.216,"SDR 9|32":0.334,"SDR 9|40":0.519,"SDR 9|50":0.801,"SDR 9|63":1.267,"SDR 9|75":1.779,"SDR 9|90":2.554,"SDR 9|110":3.782,"SDR 9|125":4.88,"SDR 9|140":6.117,"SDR 9|160":7.952,"SDR 9|180":10.027,"SDR 9|200":12.388,"SDR 9|225":15.596,"SDR 9|250":19.226,"SDR 9|280":24.106,"SDR 9|315":30.441,"SDR 11|16":0.124,"SDR 11|20":0.165,"SDR 11|25":0.216,"SDR 11|32":0.289,"SDR 11|40":0.444,"SDR 11|50":0.684,"SDR 11|63":1.075,"SDR 11|75":1.497,"SDR 11|90":2.151,"SDR 11|110":3.184,"SDR 11|125":4.111,"SDR 11|140":5.122,"SDR 11|160":6.701,"SDR 11|180":8.447,"SDR 11|200":10.395,"SDR 11|225":13.138,"SDR 11|250":16.136,"SDR 11|280":20.178,"SDR 11|315":25.494,"SDR 13.6|16":0.102,"SDR 13.6|20":0.135,"SDR 13.6|25":0.176,"SDR 13.6|32":0.234,"SDR 13.6|40":0.375,"SDR 13.6|50":0.573,"SDR 13.6|63":0.904,"SDR 13.6|75":1.255,"SDR 13.6|90":1.794,"SDR 13.6|110":2.666,"SDR 13.6|125":3.429,"SDR 13.6|140":4.288,"SDR 13.6|160":5.588,"SDR 13.6|180":7.061,"SDR 13.6|200":8.654,"SDR 13.6|225":10.954,"SDR 13.6|250":13.459,"SDR 13.6|280":16.828,"SDR 13.6|315":21.252,"SDR 17|32":0.234,"SDR 17|40":0.314,"SDR 17|50":0.484,"SDR 17|63":0.759,"SDR 17|75":1.063,"SDR 17|90":1.517,"SDR 17|110":2.241,"SDR 17|125":2.849,"SDR 17|140":3.566,"SDR 17|160":4.639,"SDR 17|180":5.853,"SDR 17|200":7.208,"SDR 17|225":9.095,"SDR 17|250":11.132,"SDR 17|280":13.93,"SDR 17|315":17.584}
										},
										{
											"apiName": "mdpe_final_quantity",
											"label": "Final Quantity",
											"type": "number",
											"formula":"(mdpe_unit_of_messurment == 'mtr' ? (mdpe_BOQ_Quantity) : mdpe_unit_of_messurment == 'Km' ? (mdpe_BOQ_Quantity * 1000): 0)",
											"isQuantity":true,
											"readOnly":true
										},
										{
											"apiName": "mdpe_Req_Raw_Material_in_MT",
											"label": "Req. Raw Material in MT",
											"required": true,
											"readOnly":true,
											"type": "number",
											"formula":"((mdpe_final_quantity *  mdpe_Weight_mtrs)/1000).toFixed(2)"
										},
										{
											"apiName": "mdpe_Realization_raw_material_conversion_cost_Kg",
											"label": "Realization(raw material+ conversion cost)/Kg",
											"isBasePrice": true,
											"type": "number",
											"formula": "mdpe_Realization_raw_material_conversion_cost_Kg ? mdpe_Realization_raw_material_conversion_cost_Kg : mdpe_pipe_b_rate"
										},
										{
											"apiName": "mdpe_Basic_Price_mtrs",
											"label": "Basic Price/mtrs",
											"readOnly":true,
											"type": "number",
											"isUnitCost":true,
											"formula":"(mdpe_Weight_mtrs * mdpe_Realization_raw_material_conversion_cost_Kg).toFixed(2)"
										},
										{
											"apiName": "mdpe_inspectionAndCommission_Charges",
											"label": "Inspection & Commission Rate/Mtr",
											"readOnly":true,
											"type":"number",
											"formula":"((mdpe_Basic_Price_mtrs * mdpe_Inspection_Commission)/100).toFixed(2)"
										},
										{
											"apiName": "mdpe_Fittings_Charges",
											"label": "Fitting Charges Rate/Mtr",
											"type": "number"
										},
										{
											"apiName": "mdpe_Freight_including_Unloading_mtrs",
											"label": "Freight Charges/Mtr",
											"type": "number",
											"disableControllingField":"mdpe_Type_of_FOR",
											"disableControllingValues":["Per Meter"]
										},
										{
											"apiName": "mdpe_Interest_Charges",
											"label": "Interest Charges/Mtr",
											"type": "number",
											"readOnly":true,
											"formula":"(((mdpe_Basic_Price_mtrs+mdpe_Fittings_Charges+mdpe_Freight_including_Unloading_mtrs+((mdpe_Basic_Price_mtrs*mdpe_Inspection_Commission)/100))*(1+mdpe_GST/100))*(mdpe_Interest_Charges_on_Payment*(mdpe_Interest_Charges_on_Payment_type/365)/100)).toFixed(2)"
										},
										{
											"apiName": "mdpe_FOR_Price",
											"label": "F.O.R. Price including Inspection, Interest Charges, BG / meter",
											"type": "number",
											"isListPrice":true,
											"readOnly":true,
											"formula":"((mdpe_Basic_Price_mtrs+mdpe_Freight_including_Unloading_mtrs+mdpe_Fittings_Charges+((mdpe_Basic_Price_mtrs*mdpe_Inspection_Commission)/100))+ mdpe_Interest_Charges).toFixed(2)"
										},
										{
											"apiName": "mdpe_GST",
											"label": "GST %",
											"type": "number",
											"readOnly":true,
											"formula": "mdpe_pipe_gst"
										},
										{
											"apiName": "mdpe_Total_Per_Mtr",
											"label": "Total Per Mtr",
											"type": "number",
											"isUnitPrice":true,
											"readOnly":true,
											"formula":"(mdpe_FOR_Price + (mdpe_FOR_Price * mdpe_GST)/100).toFixed(4)"
										},
										{
											"apiName": "mdpe_Total_Amount",
											"label": "Total Amount",
											"type": "number",
											"readOnly":true,
											"formula":"((mdpe_FOR_Price * mdpe_final_quantity) * (1 + mdpe_GST / 100)).toFixed(2)"
										}
									]
								}													
							]
						}
                    ]
                }
            }
        }
    ]
}
